/*
 * Builds a synthetic corpus to load test against.
 *
 * SYNTHETIC ON PURPOSE, AND IT IS NOT A COMPROMISE. A real corpus of this size
 * would take hours of throttled harvesting, could not be regenerated by anyone
 * reading this repo, and could never be committed to. What a load test needs
 * from a corpus is its SHAPE: how many rows, how they spread across categories
 * and channels and dates, and how often a term actually occurs. All of that is
 * reproducible, and none of it needs to be real text.
 *
 * What this deliberately does NOT do is tell you anything about answer quality.
 * That is what `evals/` is for.
 *
 *   node bench/seed.mjs ./bench.db 100000
 */
import { openSqliteCorpus } from '../packages/corpus/src/index.ts';
import { ATTR, CATEGORIES } from './queries.mjs';

const path = process.argv[2] ?? './bench.db';
const total = Number(process.argv[3] ?? 100_000);

const CHANNELS = Array.from({ length: 40 }, (_, i) => `r/place${i}`);
const START = Math.floor(Date.UTC(2023, 0, 1) / 1000);
const SPAN = Math.floor(Date.UTC(2026, 7, 1) / 1000) - START;

/* Written in batches because addDocs is one transaction per call, and one
 * transaction per record turns a 12 second seed into several minutes. */
const BATCH = 2000;

const corpus = openSqliteCorpus({ path });
const perCategory = Math.floor(total / CATEGORIES.length);
const startedAt = Date.now();
let n = 0;

for (const category of CATEGORIES) {
  for (let written = 0; written < perCategory; written += BATCH) {
    const batch = [];
    for (let i = 0; i < Math.min(BATCH, perCategory - written); i++) {
      const term = ATTR[n % ATTR.length];
      batch.push({
        source: n % 7 === 0 ? 'hackernews' : 'reddit',
        kind: n % 11 === 0 ? 'post' : 'comment',
        externalId: `x${n}`,
        channel: CHANNELS[n % CHANNELS.length],
        text: `the ${term} on these ${category} is something people mention, record ${n}, `
          + 'with enough words to look like a real comment somebody wrote on a forum '
          + 'about a product they actually bought and used for a while',
        score: n % 97,
        url: `https://example.test/${n}`,
        /* A prime stride so dates spread evenly instead of clustering, which
         * is what the trend and as-of windows need to have anything to cut. */
        createdUtc: START + ((n * 7919) % SPAN),
      });
      n++;
    }
    await corpus.addDocs(batch, category);
  }
}

const totals = await corpus.totals();
await corpus.close();
console.log(
  `seeded ${n} records into ${path} in ${((Date.now() - startedAt) / 1000).toFixed(1)}s`,
  JSON.stringify(totals),
);
